STATUS_ZH = {"pending": "等待中", "kept": "已做到", "broken": "没能做到", "said": "已提醒", "missed": "已错过", "alive": "还在", "lost": "已告别"}
STATUS_ZH.update({"active": "进行中", "paused": "暂时搁置", "completed": "已完成", "abandoned": "已放下",
                  "succeeded": "已执行", "failed": "未成功", "blocked": "暂不可行", "cancelled": "已取消"})
STATUS_ZH.update({"dream": "生成梦的片段", "narrative": "整理自我叙述"})


def t(text, /, **values):
    locale = get_locale()
    translations = MESSAGES.get(text)
    index = {"en_US": 0, "ja_JP": 1, "ko_KR": 2}.get(locale)
    if translations is None or index is None:
        return original_text(STATUS_ZH.get(text, text), **values)
    translated = translations[index]
    try:
        return translated.format(**values) if values else translated
    except (KeyError, ValueError):
        return original_text(text, **values)
